    type Bounds = gpui_kit::Bounds<gpui_kit::Pixels>;

    /// The Code, chain, Spec, and Ask tabs, then the chain's icon, as last
    /// laid out.
    fn tab_layout(window: &mut Window, cx: &mut gpui_kit::App) -> [Bounds; 5] {
        window.render_frame(cx);
        [
            window.within("code-tab").find(0usize).bounds(),
            window.within("both-tab").find(0usize).bounds(),
            window.within("spec-tab").find(0usize).bounds(),
            window.within("ask-tab").find(0usize).bounds(),
            window.find("both-icon").bounds(),
        ]
    }

    /// Draws frames until Code and Spec have slid into place, meeting when
    /// both are selected and otherwise either side of the chain, and the
    /// chain's icon is as far from what shows of Code as from what shows of
    /// Spec: a selected tab's edge, or an unselected tab's label.
    fn settle_tabs(
        handle: gpui_kit::AnyWindowHandle,
        code_selected: bool,
        spec_selected: bool,
        cx: &mut TestAppContext,
    ) -> [Bounds; 5] {
        let joined = code_selected && spec_selected;
        let inset = |selected: bool| {
            if selected {
                super::px(0.)
            } else {
                super::TAB_LABEL_INSET
            }
        };
        let start = std::time::Instant::now();
        loop {
            let layout = cx
                .update_window(handle, |_, window, cx| tab_layout(window, cx))
                .unwrap();
            let [code, chain, spec, _, icon] = layout;
            let before = icon.left() - (code.right() - inset(code_selected));
            let after = spec.left() + inset(spec_selected) - icon.right();
            let spec_offset = spec.left() - if joined { code.right() } else { chain.right() };
            if (before - after).abs() <= super::px(0.5) && spec_offset.abs() <= super::px(0.5) {
                return layout;
            }
            assert!(
                start.elapsed() < TIMEOUT,
                "the tabs did not settle: the icon is {before:?} after Code and {after:?} \
                 before Spec, and Spec is {spec_offset:?} out of place"
            );
            std::thread::sleep(Duration::from_millis(16));
        }
    }

    /// The chain is a tab like the others, with no gap either side of it, and
    /// its icon looks evenly spaced between Code and Spec whichever is
    /// selected. Selected, it gives up its width so Code and Spec meet
    /// beneath it, with the chain centred on the seam.
    #[gpui_kit::test]
    async fn chain_is_an_evenly_spaced_tab(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
        });
        let window = cx.add_window(|window, cx| {
            let input = cx.new(|cx| ChatInput::new(window, cx));
            Root::new(input, window, cx)
        });
        let handle = window.into();
        cx.wait_for(handle, TIMEOUT, |window, _| {
            window.try_find("prompt-editor").is_some()
        })
        .await;

        // Code starts selected.
        let [code, chain, spec, ask, _] = settle_tabs(handle, true, false, cx);
        for (left, right, between) in [
            (code, chain, "Code and the chain"),
            (chain, spec, "the chain and Spec"),
            (spec, ask, "Spec and Ask"),
        ] {
            assert!(
                (right.left() - left.right()).abs() <= super::px(0.5),
                "there is a gap between {between}: {left:?}, {right:?}"
            );
            assert_eq!(left.size.height, right.size.height, "{between}");
        }

        // Tab moves to the chain, which selects Code and Spec with it.
        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
            .unwrap();
        let [_, chain, spec, _, _] = settle_icon(handle, true, true, cx);
        // The facing borders either side of the chain are covered, with room
        // to spare, so no outline shows around it.
        let [seam_both, seam_spec] = cx
            .update_window(handle, |_, window, _| {
                ["seam-both", "seam-spec"].map(|id| window.find(id).bounds())
            })
            .unwrap();
        for (seam, edge, between) in [
            (seam_both, chain.left(), "Code and the chain"),
            (seam_spec, spec.left(), "the chain and Spec"),
        ] {
            assert!(
                seam.left() <= edge - super::px(2.) && seam.right() >= edge + super::px(2.),
                "the borders between {between}, at {edge:?}, are not covered: {seam:?}"
            );
            assert_eq!(
                (seam.top(), seam.bottom()),
                (chain.top(), chain.bottom()),
                "the cover between {between} is not as tall as the tabs"
            );
        }

        // Tab again moves to Spec alone.
        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
            .unwrap();
        settle_icon(handle, false, true, cx);
    }

    /// Code is tinted red and Spec blue, faintly, both together purple, a hue
    /// between the two, and Ask green. Each tab's own tint shows only while
    /// it is selected.
    #[test]
    fn tints_are_red_blue_and_purple_between() {
        let (red, blue, green) = (gpui_kit::red(), gpui_kit::blue(), gpui_kit::green());
        let (code, both, spec, ask) = (
            super::tint(red, blue, green, 0.),
            super::tint(red, blue, green, 1.),
            super::tint(red, blue, green, 2.),
            super::tint(red, blue, green, 3.),
        );
        let same = |a: gpui_kit::Hsla, b: gpui_kit::Hsla| {
            [(a.h, b.h), (a.s, b.s), (a.l, b.l)]
                .iter()
                .all(|(x, y)| (x - y).abs() < 1e-4)
        };
        assert!(same(code, red), "Code {code:?} is not {red:?}");
        assert!(same(spec, blue), "Spec {spec:?} is not {blue:?}");
        assert!(same(ask, green), "Ask {ask:?} is not {green:?}");
        for color in [code, both, spec, ask] {
            assert_eq!(color.a, super::TINT_OPACITY);
        }
        // Purple sits past blue, on the way round the hue circle to red.
        assert!(both.h > blue.h, "{both:?} is not between {blue:?} and {red:?}");

        // Rows: Code, chain, Spec, Ask. Columns: the tint at each tab.
        let shown = [
            [1., 1., 0., 0.],
            [0., 1., 0., 0.],
            [0., 1., 1., 0.],
            [0., 0., 0., 1.],
        ];
        for (ix, row) in shown.iter().enumerate() {
            for (position, expected) in row.iter().enumerate() {
                assert_eq!(
                    super::tab_tint_shown(ix, position as f32),
                    *expected,
                    "tab {ix} with the tint at {position}"
                );
            }
        }
    }

